-- RC5 internal purchasing. Images stay private and never enter catalogue RPCs.
begin;
alter table ingredient_purchase_receipt_items add column package_snapshot jsonb not null default '{}';
create function public.ops_has_permission(p_permission text) returns boolean language sql stable security definer set search_path=public as $$select auth.uid() is not null and case when current_workspace_role()='admin' then true when current_workspace_role()='inventory' then p_permission in('purchase_create','purchase_receive','operations_view') when current_workspace_role()='production' then p_permission in('purchase_create','operations_view') else false end$$;
revoke all on function public.ops_has_permission(text) from public,anon;grant execute on function public.ops_has_permission(text) to authenticated;
create table public.ingredient_purchase_identification(
 ingredient_id uuid primary key references public.ingredients(id) on delete cascade,shop_id uuid not null references public.shops(id) on delete cascade,
 brand text not null default '',package_size text not null default '',package_quantity numeric not null default 1 check(package_quantity>0),supplier_sku text not null default '',barcode text not null default '',
 original_image text,thumbnail_image text,secondary_image text,substitutes jsonb not null default '[]' check(jsonb_typeof(substitutes)='array' and jsonb_array_length(substitutes)<=20),substitute_notes text not null default '',do_not_buy text not null default '',purchase_notes text not null default '',updated_at timestamptz not null default now());
create table public.ingredient_purchasing_settings(shop_id uuid primary key references public.shops(id) on delete cascade,approval_mode text not null default 'none' check(approval_mode in('none','threshold','always')),approval_threshold numeric not null default 0 check(approval_threshold>=0),verification_required boolean not null default false);
create table public.ingredient_purchase_needs(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops(id) on delete cascade,ingredient_id uuid not null references public.ingredients(id),supplier_id uuid references public.suppliers(id),quantity numeric not null check(quantity>0),unit_cost numeric not null check(unit_cost>=0),status text not null default 'pending' check(status in('pending','approved','rejected','ordered')),source_key text,note text,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),approved_by uuid references auth.users(id),approved_at timestamptz,order_id uuid references public.ingredient_purchase_orders(id),buying_status text not null default 'needed' check(buying_status in('needed','found','substitute','unavailable')),unique(shop_id,source_key));
create table public.ingredient_supplier_offers(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops(id) on delete cascade,ingredient_id uuid not null references public.ingredients(id),supplier_id uuid not null references public.suppliers(id),package_quantity numeric not null check(package_quantity>0),package_price numeric not null check(package_price>=0),normalized_unit_cost numeric generated always as(package_price/package_quantity) stored,minimum_order numeric not null default 1 check(minimum_order>0),lead_days integer not null default 0 check(lead_days>=0),reliability integer check(reliability between 0 and 100),quality integer check(quality between 1 and 5),availability text not null default '',preferred boolean not null default false,approved boolean not null default true,created_at timestamptz not null default now(),created_by uuid not null references auth.users(id));
create table public.ingredient_purchasing_audit(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops(id) on delete cascade,ingredient_id uuid references public.ingredients(id),action text not null,old_value jsonb,new_value jsonb,reason text,user_id uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.ingredient_receiving_keys(shop_id uuid not null references public.shops(id),request_key uuid not null,payload jsonb not null,result jsonb,primary key(shop_id,request_key));
create index on public.ingredient_purchase_needs(shop_id,status,created_at desc);
create index on public.ingredient_supplier_offers(shop_id,ingredient_id,created_at desc);
create index on public.ingredient_purchasing_audit(shop_id,created_at desc);
do $$declare t text;begin foreach t in array array['ingredient_purchase_identification','ingredient_purchasing_settings','ingredient_purchase_needs','ingredient_supplier_offers','ingredient_purchasing_audit','ingredient_receiving_keys'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy internal_purchasing_read on public.%I for select to authenticated using(shop_id=public.current_shop_id() and public.current_workspace_role() in(''admin'',''inventory''))',t);end loop;end$$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('ingredient-packages','ingredient-packages',false,12582912,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy ingredient_packages_read on storage.objects for select to authenticated using(bucket_id='ingredient-packages' and (storage.foldername(name))[1]=public.current_shop_id()::text and public.ops_has_permission('operations_view'));
create policy ingredient_packages_upload on storage.objects for insert to authenticated with check(bucket_id='ingredient-packages' and (storage.foldername(name))[1]=public.current_shop_id()::text and public.ops_has_permission('ingredient_manage'));
create or replace function public.ingredient_reserved_quantity(p_id uuid) returns numeric language sql stable security definer set search_path=public as $$select 0::numeric$$;
create or replace function public.ingredient_forecast_quantity(p_id uuid) returns numeric language sql stable security definer set search_path=public as $$select 0::numeric$$;
revoke all on function public.ingredient_reserved_quantity(uuid),public.ingredient_forecast_quantity(uuid) from public,anon,authenticated;
create function public.save_ingredient_identification(p_id uuid,p_values jsonb) returns void language plpgsql security definer set search_path=public as $$declare s uuid:=current_shop_id();old jsonb;x jsonb;path text;begin
 if not ops_has_permission('ingredient_manage') then raise exception 'Administrator access required';end if;
 perform 1 from ingredients where id=p_id and shop_id=s for update;if not found then raise exception 'Ingredient not found';end if;
 if coalesce(p_values->>'package_quantity','1')::numeric<=0 or jsonb_typeof(coalesce(p_values->'substitutes','[]'))<>'array' or jsonb_array_length(coalesce(p_values->'substitutes','[]'))>20 then raise exception 'Invalid purchase identification';end if;
 for path in select value from jsonb_array_elements_text(jsonb_build_array(p_values->'original_image',p_values->'thumbnail_image',p_values->'secondary_image')) where value is not null and value<>'' loop
 if split_part(path,'/',1)<>s::text or not exists(select 1 from storage.objects where bucket_id='ingredient-packages' and name=path) then raise exception 'Private ingredient image not found';end if;end loop;
 for x in select value from jsonb_array_elements(coalesce(p_values->'substitutes','[]')) loop
 if x->>'supplier_id' is not null and x->>'supplier_id'<>'' and not exists(select 1 from suppliers where id=(x->>'supplier_id')::uuid and shop_id=s) then raise exception 'Supplier not found';end if;
 if nullif(x->>'photo','') is not null and(split_part(x->>'photo','/',1)<>s::text or not exists(select 1 from storage.objects where bucket_id='ingredient-packages' and name=x->>'photo')) then raise exception 'Private ingredient image not found';end if;end loop;
 select to_jsonb(i) into old from ingredient_purchase_identification i where ingredient_id=p_id;
 insert into ingredient_purchase_identification(ingredient_id,shop_id,brand,package_size,package_quantity,supplier_sku,barcode,original_image,thumbnail_image,secondary_image,substitutes,substitute_notes,do_not_buy,purchase_notes) values(p_id,s,left(coalesce(p_values->>'brand',''),200),left(coalesce(p_values->>'package_size',''),200),coalesce(p_values->>'package_quantity','1')::numeric,left(coalesce(p_values->>'supplier_sku',''),200),left(coalesce(p_values->>'barcode',''),100),nullif(p_values->>'original_image',''),nullif(p_values->>'thumbnail_image',''),nullif(p_values->>'secondary_image',''),coalesce(p_values->'substitutes','[]'),left(coalesce(p_values->>'substitute_notes',''),2000),left(coalesce(p_values->>'do_not_buy',''),2000),left(coalesce(p_values->>'purchase_notes',''),2000)) on conflict(ingredient_id) do update set brand=excluded.brand,package_size=excluded.package_size,package_quantity=excluded.package_quantity,supplier_sku=excluded.supplier_sku,barcode=excluded.barcode,original_image=excluded.original_image,thumbnail_image=excluded.thumbnail_image,secondary_image=excluded.secondary_image,substitutes=excluded.substitutes,substitute_notes=excluded.substitute_notes,do_not_buy=excluded.do_not_buy,purchase_notes=excluded.purchase_notes,updated_at=now();
 insert into ingredient_purchasing_audit(shop_id,ingredient_id,action,old_value,new_value,user_id) values(s,p_id,'purchase_identification',old,p_values,auth.uid());end$$;
create function public.save_ingredient_supplier_offer(p_id uuid,p_values jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare s uuid:=current_shop_id();v uuid;begin
 if not ops_has_permission('supplier_manage') then raise exception 'Administrator access required';end if;
 if not exists(select 1 from ingredients where id=p_id and shop_id=s) or not exists(select 1 from suppliers where id=(p_values->>'supplier_id')::uuid and shop_id=s and active) then raise exception 'Ingredient or supplier not found';end if;
 insert into ingredient_supplier_offers(shop_id,ingredient_id,supplier_id,package_quantity,package_price,minimum_order,lead_days,reliability,quality,availability,preferred,created_by) values(s,p_id,(p_values->>'supplier_id')::uuid,(p_values->>'package_quantity')::numeric,(p_values->>'package_price')::numeric,coalesce(p_values->>'minimum_order','1')::numeric,coalesce(p_values->>'lead_days','0')::integer,nullif(p_values->>'reliability','')::integer,nullif(p_values->>'quality','')::integer,left(coalesce(p_values->>'availability',''),200),coalesce((p_values->>'preferred')::boolean,false),auth.uid()) returning id into v;
 insert into ingredient_purchasing_audit(shop_id,ingredient_id,action,new_value,user_id) values(s,p_id,'approved_supplier_offer',p_values,auth.uid());return v;end$$;
create function public.save_ingredient_purchasing_settings(p_mode text,p_threshold numeric,p_verification boolean) returns void language plpgsql security definer set search_path=public as $$begin if not ops_has_permission('purchase_approve') then raise exception 'Administrator access required';end if;
 insert into ingredient_purchasing_settings values(current_shop_id(),p_mode,p_threshold,p_verification) on conflict(shop_id) do update set approval_mode=excluded.approval_mode,approval_threshold=excluded.approval_threshold,verification_required=excluded.verification_required;
 insert into ingredient_purchasing_audit(shop_id,action,new_value,user_id) values(current_shop_id(),'purchasing_settings',jsonb_build_object('mode',p_mode,'threshold',p_threshold,'verification',p_verification),auth.uid());end$$;
create function public.create_ingredient_purchase_need(p_id uuid,p_quantity numeric,p_supplier_id uuid,p_unit_cost numeric,p_note text) returns uuid language plpgsql security definer set search_path=public as $$declare s uuid:=current_shop_id();v uuid;cfg ingredient_purchasing_settings%rowtype;begin
 if not ops_has_permission('purchase_create') then raise exception 'Purchasing access required';end if;
 if not exists(select 1 from ingredients where id=p_id and shop_id=s and active) or(p_supplier_id is not null and not exists(select 1 from suppliers where id=p_supplier_id and shop_id=s and active)) then raise exception 'Ingredient or supplier not found';end if;
 select * into cfg from ingredient_purchasing_settings where shop_id=s; if not ops_has_permission('costs_view') then select average_unit_cost into p_unit_cost from ingredients where id=p_id and shop_id=s;end if;
 insert into ingredient_purchase_needs(shop_id,ingredient_id,supplier_id,quantity,unit_cost,status,note,created_by) values(s,p_id,p_supplier_id,p_quantity,p_unit_cost,case when cfg.approval_mode='none' or(cfg.approval_mode='threshold' and p_quantity*p_unit_cost<=cfg.approval_threshold) then 'approved' else 'pending' end,left(p_note,2000),auth.uid()) returning id into v;return v;end$$;
create function public.decide_ingredient_purchase_need(p_id uuid,p_approve boolean,p_reason text) returns void language plpgsql security definer set search_path=public as $$declare n ingredient_purchase_needs%rowtype;begin
 if not ops_has_permission('purchase_approve') then raise exception 'Purchase approval requires administrator access';end if;if length(trim(coalesce(p_reason,'')))<5 then raise exception 'A reason of at least 5 characters is required';end if;
 select * into n from ingredient_purchase_needs where id=p_id and shop_id=current_shop_id() for update;if not found or n.status<>'pending' then raise exception 'Pending purchase need not found';end if;
 update ingredient_purchase_needs set status=case when p_approve then 'approved' else 'rejected' end,approved_by=auth.uid(),approved_at=now() where id=p_id;
 insert into ingredient_purchasing_audit(shop_id,ingredient_id,action,old_value,new_value,reason,user_id) values(n.shop_id,n.ingredient_id,'purchase_approval',to_jsonb(n),jsonb_build_object('approved',p_approve),p_reason,auth.uid());end$$;
-- Preserve existing atomic ordering/receiving ledger code; extend only inventory access.
do $$declare f record;d text;begin for f in select oid from pg_proc where pronamespace='public'::regnamespace and proname in('create_ingredient_purchase_order','receive_ingredient_purchase_order') loop d:=pg_get_functiondef(f.oid);d:=regexp_replace(d,'not (public[.])?is_admin[(][)]','not (public.is_admin() or public.current_workspace_role()=''inventory'')','gi');execute d;end loop;end$$;
alter function public.create_ingredient_purchase_order(uuid,date,text,jsonb) rename to create_ingredient_purchase_order_before_approval;
revoke all on function public.create_ingredient_purchase_order_before_approval(uuid,date,text,jsonb) from public,anon,authenticated;
create function public.create_ingredient_purchase_order(p_supplier_id uuid,p_expected_date date,p_note text,p_items jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare mode text;threshold numeric;total numeric;begin
 select approval_mode,approval_threshold into mode,threshold from ingredient_purchasing_settings where shop_id=current_shop_id();select sum((x->>'ordered_quantity')::numeric*(x->>'expected_unit_cost')::numeric) into total from jsonb_array_elements(p_items)x;
 if current_setting('counternest.approved_need',true) is distinct from 'yes' and(coalesce(mode,'none')='always' or(mode='threshold' and total>threshold)) then raise exception 'Create and approve a purchase need before ordering';end if;
 return create_ingredient_purchase_order_before_approval(p_supplier_id,p_expected_date,p_note,p_items);end$$;
create function public.order_ingredient_purchase_need(p_id uuid) returns uuid language plpgsql security definer set search_path=public as $$declare n ingredient_purchase_needs%rowtype;v uuid;begin
 if not ops_has_permission('purchase_create') then raise exception 'Purchasing access required';end if;
 select * into n from ingredient_purchase_needs where id=p_id and shop_id=current_shop_id() for update;if not found then raise exception 'Purchase need not found';end if;if n.order_id is not null then return n.order_id;end if;if n.status<>'approved' then raise exception 'Purchase approval is required';end if;
 perform set_config('counternest.approved_need','yes',true);v:=create_ingredient_purchase_order(n.supplier_id,null,n.note,jsonb_build_array(jsonb_build_object('ingredient_id',n.ingredient_id,'ordered_quantity',n.quantity,'expected_unit_cost',n.unit_cost)));perform set_config('counternest.approved_need','',true);
 update ingredient_purchase_needs set order_id=v,status='ordered' where id=p_id;return v;end$$;
create function public.verify_ingredient_package(p_id uuid,p_barcode text,p_checks jsonb,p_override_reason text default null) returns text language plpgsql security definer set search_path=public as $$declare i ingredient_purchase_identification%rowtype;result text:='not_approved';checks_ok boolean;begin
 if not ops_has_permission('purchase_receive') then raise exception 'Purchasing access required';end if;
 if not exists(select 1 from ingredients where id=p_id and shop_id=current_shop_id()) then raise exception 'Ingredient not found';end if;
 select * into i from ingredient_purchase_identification where ingredient_id=p_id and shop_id=current_shop_id();
 if nullif(trim(p_barcode),'') is not null and trim(p_barcode)=i.barcode then result:='preferred';elsif nullif(trim(p_barcode),'') is not null and exists(select 1 from jsonb_array_elements(i.substitutes)x where x->>'barcode'=trim(p_barcode)) then result:='substitute';end if;
 checks_ok:=coalesce((p_checks->>'ingredient')::boolean,false) and coalesce((p_checks->>'brand')::boolean,false) and coalesce((p_checks->>'size')::boolean,false) and coalesce((p_checks->>'condition')::boolean,false) and coalesce((p_checks->>'barcode')::boolean,false);
 if result='not_approved' or not checks_ok then
 if not ops_has_permission('purchase_override') or length(trim(coalesce(p_override_reason,'')))<5 then raise exception 'Package mismatch requires administrator override and reason';end if;
 insert into ingredient_purchasing_audit(shop_id,ingredient_id,action,new_value,reason,user_id) values(current_shop_id(),p_id,'barcode_or_checklist_override',jsonb_build_object('barcode',p_barcode,'checks',p_checks,'match',result),p_override_reason,auth.uid());result:='override';end if;return result;end$$;
create function public.set_ingredient_buying_status(p_id uuid,p_status text,p_barcode text default null,p_override_reason text default null) returns void language plpgsql security definer set search_path=public as $$declare n ingredient_purchase_needs%rowtype;m text;begin
 if not ops_has_permission('purchase_create') then raise exception 'Purchasing access required';end if;
 select * into n from ingredient_purchase_needs where id=p_id and shop_id=current_shop_id() for update;if not found or n.status not in('approved','ordered') then raise exception 'Approved purchase need not found';end if;
 if p_status not in('needed','found','substitute','unavailable') then raise exception 'Invalid buying status';end if;
 if p_status in('found','substitute') then m:=verify_ingredient_package(n.ingredient_id,p_barcode,'{"ingredient":true,"brand":true,"size":true,"condition":true,"barcode":true}',p_override_reason);if m='substitute' then p_status:='substitute';end if;end if;
 update ingredient_purchase_needs set buying_status=p_status where id=p_id;
 insert into ingredient_purchasing_audit(shop_id,ingredient_id,action,old_value,new_value,reason,user_id) values(n.shop_id,n.ingredient_id,'buying_status',jsonb_build_object('status',n.buying_status),jsonb_build_object('status',p_status,'barcode',p_barcode),p_override_reason,auth.uid());end$$;
alter function public.receive_ingredient_purchase_order(uuid,text,text,jsonb) rename to receive_ingredient_purchase_order_before_verification;
revoke all on function public.receive_ingredient_purchase_order_before_verification(uuid,text,text,jsonb) from public,anon,authenticated;
create function public.receive_ingredient_purchase_order(p_order_id uuid,p_invoice_reference text,p_note text,p_items jsonb) returns jsonb language plpgsql security definer set search_path=public as $$begin
 if exists(select 1 from ingredient_purchasing_settings where shop_id=current_shop_id() and verification_required) then raise exception 'Use verified receiving for this workspace';end if;
 return receive_ingredient_purchase_order_before_verification(p_order_id,p_invoice_reference,p_note,p_items);end$$;
create function public.verified_receive_ingredient_order(p_order_id uuid,p_key uuid,p_invoice text,p_note text,p_items jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare s uuid:=current_shop_id();line jsonb;ingredient uuid;v jsonb;payload jsonb:=jsonb_build_object('order',p_order_id,'invoice',p_invoice,'note',p_note,'items',p_items);saved ingredient_receiving_keys%rowtype;begin
 if not ops_has_permission('purchase_receive') then raise exception 'Purchasing access required';end if;if p_key is null then raise exception 'Receiving request key is required';end if;
 insert into ingredient_receiving_keys(shop_id,request_key,payload) values(s,p_key,payload) on conflict do nothing;select * into saved from ingredient_receiving_keys where shop_id=s and request_key=p_key for update;
 if saved.payload<>payload then raise exception 'Receiving retry details changed';end if;if saved.result is not null then return saved.result;end if;
 if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'At least one receipt line is required';end if;
 for line in select value from jsonb_array_elements(p_items) loop
 select ingredient_id into ingredient from ingredient_purchase_order_items where id=(line->>'order_item_id')::uuid and order_id=p_order_id and shop_id=s;if ingredient is null then raise exception 'Purchase-order line not found';end if;
 perform verify_ingredient_package(ingredient,line->>'barcode',line->'checks',line->>'override_reason');end loop;
 v:=receive_ingredient_purchase_order_before_verification(p_order_id,p_invoice,p_note,p_items);
 for line in select value from jsonb_array_elements(p_items) loop
  update ingredient_purchase_receipt_items li set package_snapshot=coalesce((select sub from ingredient_purchase_identification pi cross join lateral jsonb_array_elements(pi.substitutes) sub where pi.ingredient_id=li.ingredient_id and pi.shop_id=s and nullif(sub->>'barcode','')=line->>'barcode' order by coalesce(nullif(sub->>'priority',''),'999')::numeric limit 1),(select jsonb_build_object('brand',pi.brand,'package_size',pi.package_size,'barcode',pi.barcode) from ingredient_purchase_identification pi where pi.ingredient_id=li.ingredient_id and pi.shop_id=s),'{}'::jsonb) where li.receipt_id=(v->>'receipt_id')::uuid and li.order_item_id=(line->>'order_item_id')::uuid and li.shop_id=s;
 end loop;update ingredient_receiving_keys set result=v where shop_id=s and request_key=p_key;return v;end$$;
-- Prevent the legacy no-PO stock route bypassing required package verification.
alter function public.receive_ingredient_stock(uuid,uuid,numeric,numeric,numeric,text,text) rename to receive_ingredient_stock_before_verification;
revoke all on function public.receive_ingredient_stock_before_verification(uuid,uuid,numeric,numeric,numeric,text,text) from public,anon,authenticated;
create function public.receive_ingredient_stock(p_ingredient_id uuid,p_supplier_id uuid,p_packages numeric,p_quantity_per_package numeric,p_cost_per_package numeric,p_invoice_reference text default null,p_note text default null) returns jsonb language plpgsql security definer set search_path=public as $$begin
 if exists(select 1 from ingredient_purchasing_settings where shop_id=current_shop_id() and verification_required) then raise exception 'Use verified purchase-order receiving for this workspace';end if;return receive_ingredient_stock_before_verification(p_ingredient_id,p_supplier_id,p_packages,p_quantity_per_package,p_cost_per_package,p_invoice_reference,p_note);end$$;
create function public.get_ingredient_purchasing(p_search text default '',p_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=public as $$declare s uuid:=current_shop_id();begin
 if not ops_has_permission('operations_view') then raise exception 'Purchasing access required';end if;
 return jsonb_build_object('shop_id',s,'permissions',(select coalesce(jsonb_agg(p),'[]') from unnest(array['ingredient_manage','purchase_create','purchase_approve','purchase_receive','purchase_override','supplier_manage','operations_view','costs_view'])p where ops_has_permission(p)),'settings',coalesce((select to_jsonb(c) from ingredient_purchasing_settings c where shop_id=s),'{"approval_mode":"none","approval_threshold":0,"verification_required":false}'::jsonb),
 'suppliers',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'phone',case when current_workspace_role()='production' then null else phone end,'email',case when current_workspace_role()='production' then null else email end)),'[]') from suppliers where shop_id=s and active),
 'ingredients',(select coalesce(jsonb_agg(to_jsonb(q)),'[]') from(select i.id,i.name,i.base_unit,i.current_quantity,i.reorder_level,i.target_level,case when ops_has_permission('costs_view') then i.average_unit_cost else null end average_unit_cost,i.preferred_supplier_id,coalesce((select package_quantity from ingredient_supplier_offers where ingredient_id=i.id and shop_id=s and approved order by preferred desc,created_at desc limit 1),pi.package_quantity,1) purchase_pack_size,case when ops_has_permission('purchase_receive') then coalesce(to_jsonb(pi),'{}') else coalesce(to_jsonb(pi),'{}')-'original_image'-'thumbnail_image'-'secondary_image'-'substitutes' end identification,
 coalesce((select sum(ordered_quantity-received_quantity) from ingredient_purchase_order_items li join ingredient_purchase_orders po on po.id=li.order_id where li.ingredient_id=i.id and li.shop_id=s and po.status in('ordered','partially_received')),0) incoming_quantity,ingredient_reserved_quantity(i.id) reserved_quantity,ingredient_forecast_quantity(i.id) forecast_quantity,
 (select coalesce(jsonb_agg(to_jsonb(o)),'[]') from(select f.*,sp.name supplier_name from ingredient_supplier_offers f join suppliers sp on sp.id=f.supplier_id where f.ingredient_id=i.id and f.shop_id=s and ops_has_permission('costs_view') order by f.created_at desc limit 100)o) offers,
 (select coalesce(jsonb_agg(to_jsonb(h)),'[]') from(select r.received_at,sp.name supplier_name,li.quantity_received quantity,li.actual_unit_cost normalized_unit_cost,li.actual_unit_cost*li.quantity_received price,li.package_snapshot from ingredient_purchase_receipt_items li join ingredient_purchase_receipts r on r.id=li.receipt_id join suppliers sp on sp.id=r.supplier_id where li.ingredient_id=i.id and li.shop_id=s and ops_has_permission('costs_view') order by r.received_at desc limit 30)h) price_history
 from ingredients i left join ingredient_purchase_identification pi on pi.ingredient_id=i.id and pi.shop_id=s where i.shop_id=s and i.active and i.name ilike '%'||left(coalesce(p_search,''),100)||'%' order by i.name limit 40 offset greatest(0,least(coalesce(p_offset,0),100000)))q),
 'needs',(select coalesce(jsonb_agg(case when ops_has_permission('costs_view') then to_jsonb(n) else to_jsonb(n)-'unit_cost' end),'[]') from(select x.*,i.name ingredient_name from ingredient_purchase_needs x join ingredients i on i.id=x.ingredient_id where x.shop_id=s and(ops_has_permission('purchase_receive') or ops_has_permission('purchase_approve') or x.created_by=auth.uid()) order by x.created_at desc limit 100)n),
 'orders',(select coalesce(jsonb_agg(to_jsonb(o)),'[]') from(select po.id,po.order_number,po.supplier_id,sp.name supplier_name,po.expected_date,po.status,(select coalesce(jsonb_agg(case when ops_has_permission('costs_view') then to_jsonb(li) else to_jsonb(li)-'expected_unit_cost'-'line_total' end),'[]') from ingredient_purchase_order_items li where li.order_id=po.id and li.shop_id=s) items from ingredient_purchase_orders po join suppliers sp on sp.id=po.supplier_id where po.shop_id=s and po.status in('ordered','partially_received') and ops_has_permission('purchase_receive') order by po.ordered_at desc limit 60)o),
 'audit',(select coalesce(jsonb_agg(to_jsonb(a)),'[]') from(select * from ingredient_purchasing_audit where shop_id=s and ops_has_permission('purchase_approve') order by created_at desc limit 50)a));end$$;
create function public.get_ingredient_package_cards(p_ids uuid[]) returns jsonb language plpgsql stable security definer set search_path=public as $$begin
 if not ops_has_permission('purchase_receive') then raise exception 'Purchasing access required';end if;
 if cardinality(p_ids)>100 then raise exception 'Request at most 100 ingredient cards';end if;
 return(select coalesce(jsonb_agg(jsonb_build_object('id',i.id,'name',i.name,'base_unit',i.base_unit,'current_quantity',i.current_quantity,'average_unit_cost',case when ops_has_permission('costs_view') then i.average_unit_cost else null end,'reorder_level',i.reorder_level,'target_level',i.target_level,'preferred_supplier_id',i.preferred_supplier_id,'incoming_quantity',0,'reserved_quantity',ingredient_reserved_quantity(i.id),'forecast_quantity',ingredient_forecast_quantity(i.id),'identification',coalesce(to_jsonb(pi),'{}'),'offers','[]'::jsonb,'price_history','[]'::jsonb)),'[]') from ingredients i left join ingredient_purchase_identification pi on pi.ingredient_id=i.id and pi.shop_id=i.shop_id where i.shop_id=current_shop_id() and i.id=any(p_ids));end$$;
do $$declare f record;begin for f in select oid::regprocedure signature from pg_proc where pronamespace='public'::regnamespace and proname in('save_ingredient_identification','save_ingredient_supplier_offer','save_ingredient_purchasing_settings','create_ingredient_purchase_need','decide_ingredient_purchase_need','order_ingredient_purchase_need','verify_ingredient_package','set_ingredient_buying_status','verified_receive_ingredient_order','get_ingredient_purchasing','get_ingredient_package_cards','create_ingredient_purchase_order','receive_ingredient_purchase_order','receive_ingredient_stock') loop execute format('revoke all on function %s from public,anon',f.signature);execute format('grant execute on function %s to authenticated',f.signature);end loop;end$$;
commit;
